class Expense(
    val category: String,
    val amount: Double,
) {
    init {
        require(category.isNotBlank())
        require(amount > 0.0)
    }

    fun summary(): String = "$category: £$amount"
}

interface ExpenseStore {
    fun save(expense: Expense)
}

class InMemoryExpenseStore : ExpenseStore {
    private val items = mutableListOf<Expense>()

    override fun save(expense: Expense) {
        items += expense
    }
}

class ExpenseService(
    private val store: ExpenseStore,
) {
    fun record(category: String, amount: Double): Expense {
        val expense = Expense(category, amount)
        store.save(expense)
        return expense
    }
}

