interface ExpenseStore { fun save(expense: Expense) }
class ConsoleStore : ExpenseStore {
    override fun save(expense: Expense) = println("Saved ${expense.category}")
}
data class Expense(val category: String, val amount: Double)
class Recorder(private val store: ExpenseStore) {
    fun record(category: String, amount: Double) {
        require(amount > 0.0)
        store.save(Expense(category, amount))
    }
}
fun main() { Recorder(ConsoleStore()).record("Food", 8.5) }
